   "codice": "extends \"res://htd/htd_test.gd\"\n\n\nfunc _run_tests() -> void:\n\tvar main := await instantiate_main_scene()\n\tif not check(\"main\", main != null, \"La scena principale deve caricarsi senza errori\"):\n\t\treturn\n\tvar sub := find_by_name(main, \"Submarine\") as Sprite2D\n\tif not check(\"sub\", sub != null, \"La scena deve contenere il nodo Submarine\"):\n\t\treturn\n\tsub.position = Vector2(400, 300)\n\tawait hold_action(\"surface\", 10)\n\tcheck(\"surface\", sub.position.y < 300.0, \"Tenendo premuto surface il sottomarino deve salire verso l'alto\")\n\tsub.position = Vector2(400, 300)\n\tawait hold_action(\"dive\", 10)\n\tcheck(\"dive\", sub.position.y > 300.0, \"Tenendo premuto dive il sottomarino deve scendere verso il basso\")\n\tsub.position = Vector2(400, 50.0)\n\tawait hold_action(\"surface\", 5)\n\tcheck(\"clamp_surface\", absf(sub.position.y - 80.0) < 0.5, \"Continuando a salire il sottomarino deve fermarsi a 80 pixel alla superficie (è a y = %.1f)\" % sub.position.y)\n\tsub.position = Vector2(400, 1000.0)\n\tawait hold_action(\"dive\", 5)\n\tcheck(\"clamp_dive\", absf(sub.position.y - 560.0) < 0.5, \"Continuando a scendere il sottomarino deve fermarsi a 560 pixel sul fondale (è a y = %.1f)\" % sub.position.y)\n",
